//! 🧪️ The original document source admits its fixed recipient before verified genesis under the mounted policy.
use crate::fixture;
use semio_framework_plugin_ownership::original_store_genesis::{OriginalStoreGenesis,OriginalStoreSlot};
use semio_framework_job::*;
use semio_framework_value::{RetainedCloneGrant,RetainedCloneProgress,RetainedCloneStep};
type Source=OriginalStoreGenesis<fixture::ScalarGenesis<false>>;
const POLICY:RetainedCloneGrant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:32768,maximum_capacity_bytes:16<<20,maximum_release_bytes:16<<20,maximum_depth:4096};
fn call<T>(caller:&mut OriginalJobFixtureCaller,decoder:&mut OriginalJobDecodeOwner,policy:RetainedCloneGrant,f:impl FnOnce(&mut StepContext<'_>)->Result<T,OriginalTurnFailure>)->T{let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||caller.turn_with_decoder(policy,decoder,f));let p=caller.receipt();assert_eq!((heap.requested_bytes,heap.released_bytes),(p.retained_capacity_bytes,p.released_bytes),"original source receipt {p:?}, failure {:?}",result.as_ref().err());result.unwrap()}
fn finish(mut source:Option<Box<Source>>,caller:&mut OriginalJobFixtureCaller,decoder:&mut OriginalJobDecodeOwner){for turn in 0..1048576{if source.as_ref().unwrap().terminal_is_empty(){break}call(caller,decoder,POLICY,|cx|cx.with_original_retirement(|cx|source.as_mut().unwrap().close_step(cx).map(|_|())));assert!(turn<1048575,"original source close retained its actual native frontier");}call(caller,decoder,POLICY,|cx|cx.with_original_retirement(|cx|{let d=Source::boxed_release_demands();close_original_retained_step(cx,d,|_|{source.take();Ok(RetainedCloneStep::Complete(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,released_bytes:d.release_bytes,..Default::default()}))})?;Ok(())}));}
#[test]fn original_document_genesis_completes_under_the_actual_mounted_header_policy(){
 let law:serde_json::Value=serde_json::from_str(include_str!("🔣️.json")).unwrap();assert_eq!(law["maximumHeaderCopyBytes"],POLICY.maximum_copy_bytes);assert_eq!(law["historyShape"],"Document");
 let mut caller=crate::caller();let mut decoder=OriginalJobDecodeOwner::empty();let actor=semio_framework_os_kernel::ActorId("actual-mount".into());let mut source=call(&mut caller,&mut decoder,POLICY,|cx|Source::admit("native-document",&actor,cx));let mut result=None;
 for turn in 0..1048576{result=call(&mut caller,&mut decoder,POLICY,|cx|source.as_mut().unwrap().step(cx));if result.is_some(){break}assert!(turn<1048575,"native document genesis stalled {:?}",source.as_ref().unwrap().progress());}
 let(address,store)=result.unwrap();assert_eq!(address,"native-document");assert_eq!(store.envelope().history_shape,semio_framework_os_kernel::HistoryShape::Document);assert_eq!(store.snapshot().unwrap().zoom,1.25);assert!(store.owners.snapshot_read_leases.authority_matches(store.cursor.generation,store.cursor.content_revision),"initialized native Store must publish its exact original snapshot authority");finish(source,&mut caller,&mut decoder);
 let mut store=OriginalStoreSlot::from_original(store);for turn in 0..1048576{if store.terminal_is_empty(){break}call(&mut caller,&mut decoder,POLICY,|cx|cx.with_original_retirement(|cx|store.close_step(cx)));assert!(turn<1048575,"native document Store close retained its actual original owner");}assert!(store.terminal_is_empty());crate::retire_decoder(&mut caller,&mut decoder);caller.retire(POLICY);
}
#[test]fn original_pending_initializer_header_denials_and_token_cancellation_keep_actual_custody(){
 for after_envelope in [false,true]{let mut caller=crate::caller();let mut decoder=OriginalJobDecodeOwner::empty();let actor=semio_framework_os_kernel::ActorId("actual-cancel".into());let mut source=call(&mut caller,&mut decoder,POLICY,|cx|Source::admit("native-cancel",&actor,cx));
 for turn in 0..1048576{if source.as_ref().unwrap().progress().0==5{break}call(&mut caller,&mut decoder,POLICY,|cx|source.as_mut().unwrap().step(cx));assert!(turn<1048575);}
 for axis in 0..4{let mut denied=POLICY;match axis{0=>denied.maximum_items=0,1=>denied.maximum_copy_bytes=0,2=>denied.maximum_capacity_bytes=0,_=>denied.maximum_depth=0};assert!(call(&mut caller,&mut decoder,denied,|cx|source.as_mut().unwrap().step(cx)).is_none());assert_eq!(caller.receipt(),RetainedCloneProgress::default());assert!(!source.as_ref().unwrap().initializer_is_awaiting_envelope());}
 call(&mut caller,&mut decoder,POLICY,|cx|source.as_mut().unwrap().step(cx));assert!(source.as_ref().unwrap().initializer_is_awaiting_envelope());if after_envelope{call(&mut caller,&mut decoder,POLICY,|cx|source.as_mut().unwrap().step(cx));assert!(!source.as_ref().unwrap().initializer_is_awaiting_envelope());assert_eq!(source.as_ref().unwrap().progress().0,6);}
 caller.cancel().cancel_now();finish(source,&mut caller,&mut decoder);crate::retire_decoder(&mut caller,&mut decoder);caller.retire(POLICY);}
}
